 CREATE OR REPLACE FUNCTION public.getcurrentdaysrecordingdtls()                                                                                                                                                                                                                                                                                                                                                                                                                                                   
  RETURNS TABLE(danumber character varying, progressnoteid uuid, author character varying, createddate character varying, createddateformatted character varying, recordingtype text, recordingsubtype character varying, title character varying, teamname character varying, draftind character varying, attemptind character varying, contactdate character varying, contactname character varying, contactrole character varying, contactphone character varying, contactemail character varying, details text)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
 RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 SELECT  distinct                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 (select servicerequestnumber from intakeservicerequest where intakeserviceid =PN.Entitytypeid::uuid) as DANumber,                                                                                                                                                                                                                                                                                                                                                                                                 
         PN.ProgressNoteId,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
        CASE WHEN (PNT.ProgressNoteClassificationTypeKey = 'System')                                                                                                                                                                                                                                                                                                                                                                                                                                               
             THEN 'System'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
             ELSE COALESCE(UP.DisplayName, '')                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
         END AS Author,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
        COALESCE(PN.insertedon::character varying, '') AS CreatedDate,                                                                                                                                                                                                                                                                                                                                                                                                                                             
        COALESCE(PN.insertedon::character varying, '') AS CreatedDateFormatted,                                                                                                                                                                                                                                                                                                                                                                                                                                    
         (select description from progressnotetype where progressnotetypeid  = PN.ProgressNotetypeId) AS RecordingType,                                                                                                                                                                                                                                                                                                                                                                                            
         (select ProgressNoteTypeKey from progressnotetype where progressnotetypeid  = PN.ProgressNotesubtypeId) AS RecordingSubType,                                                                                                                                                                                                                                                                                                                                                                              
        --COALESCE(PNT.Description, '') AS RecordingType,                                                                                                                                                                                                                                                                                                                                                                                                                                                          
        --COALESCE(PNT.ProgressNoteTypeKey, '') AS RecordingSubType,                                                                                                                                                                                                                                                                                                                                                                                                                                               
        CASE WHEN (PNT.ProgressNoteClassificationTypeKey = 'System')                                                                                                                                                                                                                                                                                                                                                                                                                                               
             THEN ''                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
             ELSE COALESCE(TM.RoleTypeKey, '')                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
        END AS Title,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
        CASE WHEN (PNT.ProgressNoteClassificationTypeKey = 'System')                                                                                                                                                                                                                                                                                                                                                                                                                                               
             THEN ''                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
             ELSE COALESCE(TE.TeamName, '')                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
        END AS TeamName,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
        CASE WHEN (PNT.ProgressNoteClassificationTypeKey = 'System')                                                                                                                                                                                                                                                                                                                                                                                                                                               
             THEN ''                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
             ELSE COALESCE(PN.SaveMode::character varying, '')                                                                                                                                                                                                                                                                                                                                                                                                                                                     
        END AS DraftInd,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
        CASE WHEN (PNT.ProgressNoteClassificationTypeKey = 'System')                                                                                                                                                                                                                                                                                                                                                                                                                                               
             THEN ''                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
             ELSE COALESCE(PN.AttemptIndicator::character varying, '')                                                                                                                                                                                                                                                                                                                                                                                                                                             
        END AS AttemptInd,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
        COALESCE (PN.ContactDate::character varying,'') AS ContactDate,                                                                                                                                                                                                                                                                                                                                                                                                                                            
        COALESCE (PN.ContactName, '') AS ContactName,                                                                                                                                                                                                                                                                                                                                                                                                                                                              
        COALESCE(PN.ContactRoleTypeKey, '') AS ContactRole,                                                                                                                                                                                                                                                                                                                                                                                                                                                        
        COALESCE(PN.ContactPhone, '') AS ContactPhone,                                                                                                                                                                                                                                                                                                                                                                                                                                                             
        COALESCE(PN.ContactEmail, '') AS ContactEmail,                                                                                                                                                                                                                                                                                                                                                                                                                                                             
        COALESCE(PND.Description, '') AS Details                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
   FROM IntakeServiceRequest AS ISR INNER JOIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
        ProgressNote AS PN ON CAST(ISR.IntakeServiceId AS VARCHAR(50)) = PN.EntityTypeId INNER JOIN                                                                                                                                                                                                                                                                                                                                                                                                                
        ProgressNoteDetail AS PND ON PND.ProgressNoteId = PN.ProgressNoteId INNER JOIN                                                                                                                                                                                                                                                                                                                                                                                                                             
        ProgressNoteType AS PNT ON PNT.ProgressNoteTypeId = PN.ProgressNoteTypeId INNER JOIN                                                                                                                                                                                                                                                                                                                                                                                                                       
        UserProfile AS UP ON UP.SecurityUsersId = PN.insertedby INNER JOIN                                                                                                                                                                                                                                                                                                                                                                                                                                         
        TeamMemberAssignment AS TMA ON TMA.SecurityUsersId = PN.insertedby INNER JOIN                                                                                                                                                                                                                                                                                                                                                                                                                              
        TeamMember AS TM ON TM.TeamMemberId = TMA.TeamMemberId INNER JOIN                                                                                                                                                                                                                                                                                                                                                                                                                                          
        Team AS TE ON TE.TeamId = TM.TeamId LEFT OUTER JOIN                                                                                                                                                                                                                                                                                                                                                                                                                                                        
        ProgressNoteCustomForm AS PNCF ON PNCF.ProgressNoteId = PN.ProgressNoteId LEFT OUTER JOIN                                                                                                                                                                                                                                                                                                                                                                                                                  
        ProgressNoteCustomFormResult AS PNCFR ON PNCFR.ProgressNoteCustomFormId = PNCF.ProgressNoteCustomFormId                                                                                                                                                                                                                                                                                                                                                                                                    
        where PN.insertedon::date between now()::Date - 7 and now()::date                                                                                                                                                                                                                                                                                                                                                                                                                                          
        ORDER BY createddate desc;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        

